function Mouse({ render }) {
  const [pos, setPos] = useState({ x: 0, y: 0 });
  return (
    <div style={{ height: '100vh' }} onMouseMove={(e) => setPos({ x: e.clientX, y: e.clientY })}>
      {render(pos)}                       {/* caller decides the markup */}
    </div>
  );
}
